        if char.isdigit():
            count += 1
    return count

def odd_position(lst):
    for i in range(1, len(lst), 2):
        if lst[i] % 2 == 0:
            return False
    return True

def pack_consecutive_duplicates(lst):
    result = []
    if not lst:
        return result
    current_pack = [lst[0]]
    for elem in lst[1:]:
        if elem == current_pack[-1]:
            current_pack.append(elem)
        else:
            result.append(current_pack)
            current_pack = [elem]
    result.append(current_pack)
    return result

import math

def surfacearea_sphere(radius):
    if radius < 0:
        raise ValueError("Radius cannot be negative")
    return 4 * math.pi * radius ** 2

def find_substring(lst, substring):
    if substring == "":
        return True
    for string in lst:
        if substring in string:
            return True
    return False
